// Peer-to-peer networking via PeerJS (WebRTC). The host is authoritative;
// clients send inputs/actions and receive snapshots/events.
const PREFIX = 'opuslethal55-';
const ICE = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun.cloudflare.com:3478' },
    { urls: 'turn:openrelay.metered.ca:80', username: 'openrelayproject', credential: 'openrelayproject' },
    { urls: 'turn:openrelay.metered.ca:443', username: 'openrelayproject', credential: 'openrelayproject' },
  ],
};

export class Net {
  constructor() {
    this.peer = null;
    this.conns = new Map();
    this.hostConn = null;
    this.isHost = false;
    this.online = false;
    this.id = 'solo';
    this.handlers = {};
  }
  on(t, f) { this.handlers[t] = f; }

  _mkPeer(id) {
    // eslint-disable-next-line no-undef
    return id ? new Peer(PREFIX + id, { debug: 0, config: ICE }) : new Peer({ debug: 0, config: ICE });
  }

  host(code) {
    return new Promise((res, rej) => {
      if (typeof Peer === 'undefined') return rej(new Error('PeerJS unavailable'));
      const p = this.peer = this._mkPeer(code);
      const to = setTimeout(() => rej(new Error('Timed out contacting matchmaking server')), 15000);
      p.on('open', (id) => { clearTimeout(to); this.id = id; this.isHost = true; this.online = true; res(id); });
      p.on('error', (e) => { clearTimeout(to); if (!this.online) rej(e); else console.warn('peer error', e); });
      p.on('connection', (c) => this._setup(c));
      p.on('call', (call) => this.handlers.call && this.handlers.call(call));
      p.on('disconnected', () => { try { p.reconnect(); } catch (e) { } });
    });
  }

  join(code) {
    return new Promise((res, rej) => {
      if (typeof Peer === 'undefined') return rej(new Error('PeerJS unavailable'));
      const p = this.peer = this._mkPeer();
      const to = setTimeout(() => rej(new Error('Could not reach host (timed out). Check the code.')), 20000);
      p.on('error', (e) => {
        if (!this.online) { clearTimeout(to); rej(e.type === 'peer-unavailable' ? new Error('No crew found with that code.') : e); }
      });
      p.on('call', (call) => this.handlers.call && this.handlers.call(call));
      p.on('open', (id) => {
        this.id = id;
        const c = p.connect(PREFIX + code, { reliable: true, serialization: 'json' });
        c.on('open', () => { clearTimeout(to); this.hostConn = c; this.online = true; this.hostId = c.peer; res(id); });
        c.on('data', (d) => this._recv(c.peer, d));
        c.on('close', () => this.handlers.disconnect && this.handlers.disconnect());
        c.on('error', () => { });
      });
    });
  }

  solo() { this.isHost = true; this.id = 'solo-' + Math.random().toString(36).slice(2, 7); }

  _setup(c) {
    c.on('open', () => { this.conns.set(c.peer, c); this.handlers.peerJoin && this.handlers.peerJoin(c.peer); });
    c.on('data', (d) => this._recv(c.peer, d));
    c.on('close', () => { if (this.conns.delete(c.peer)) this.handlers.peerLeave && this.handlers.peerLeave(c.peer); });
    c.on('error', () => { });
  }

  _recv(from, d) {
    if (!d || typeof d !== 'object') return;
    const h = this.handlers[d.t];
    if (h) { try { h(d, from); } catch (e) { console.error('net handler', d.t, e); } }
  }

  // client -> host (loops back locally on the host)
  send(msg) {
    if (this.isHost) this._recv(this.id, msg);
    else if (this.hostConn && this.hostConn.open) this.hostConn.send(msg);
  }
  broadcast(msg) {
    for (const c of this.conns.values()) if (c.open) { try { c.send(msg); } catch (e) { } }
  }
  sendTo(pid, msg) {
    if (pid === this.id) this._recv(this.id, msg);
    else { const c = this.conns.get(pid); if (c && c.open) c.send(msg); }
  }
  call(pid, stream) { return this.peer ? this.peer.call(pid, stream) : null; }
}

