import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

export const ASSET_BASES = [
  'https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/',
  'https://raw.githubusercontent.com/mrdoob/three.js/r160/examples/',
];

export const Assets = { tex: {}, models: {} };

const TEXTURES = {
  brick: 'textures/brick_diffuse.jpg',
  wood: 'textures/hardwood2_diffuse.jpg',
  grass: 'textures/terrain/grasslight-big.jpg',
  floor: 'textures/floors/FloorsCheckerboard_S_Diffuse.jpg',
  crate: 'textures/crate.gif',
  moon: 'textures/planets/moon_1024.jpg',
};
const MODELS = {
  robot: 'models/gltf/RobotExpressive/RobotExpressive.glb',
  soldier: 'models/gltf/Soldier.glb',
  xbot: 'models/gltf/Xbot.glb',
};

async function tryBases(fn) {
  let err;
  for (const b of ASSET_BASES) {
    try { return await fn(b); } catch (e) { err = e; }
  }
  throw err;
}

function withTimeout(p, ms) {
  return Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))]);
}

export async function loadAll(onProgress) {
  const tl = new THREE.TextureLoader();
  tl.setCrossOrigin('anonymous');
  const gl = new GLTFLoader();
  gl.setCrossOrigin('anonymous');
  const jobs = [];
  let done = 0;
  const total = Object.keys(TEXTURES).length + Object.keys(MODELS).length;
  const tick = (name, ok) => { done++; onProgress && onProgress(done / total, name, ok); };
  for (const [k, p] of Object.entries(TEXTURES)) {
    jobs.push(withTimeout(tryBases((b) => tl.loadAsync(b + p)), 20000)
      .then((t) => { t.wrapS = t.wrapT = THREE.RepeatWrapping; t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; Assets.tex[k] = t; tick(k, true); })
      .catch(() => tick(k, false)));
  }
  for (const [k, p] of Object.entries(MODELS)) {
    jobs.push(withTimeout(tryBases((b) => gl.loadAsync(b + p)), 30000)
      .then((g) => { Assets.models[k] = g; tick(k, true); })
      .catch(() => tick(k, false)));
  }
  await Promise.all(jobs);
}

export function tex(name, rx = 1, ry = 1) {
  const t = Assets.tex[name];
  if (!t) return null;
  const c = t.clone();
  c.needsUpdate = true;
  c.repeat.set(rx, ry);
  return c;
}

// Procedural canvas textures used for signage and panels
export function canvasTex(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function panelTexture(base = '#6b6f73') {
  return canvasTex(256, 256, (g, w, h) => {
    g.fillStyle = base; g.fillRect(0, 0, w, h);
    for (let i = 0; i < 2000; i++) {
      g.fillStyle = `rgba(0,0,0,${Math.random() * 0.06})`;
      g.fillRect(Math.random() * w, Math.random() * h, 2, 2);
    }
    g.strokeStyle = 'rgba(0,0,0,0.45)'; g.lineWidth = 3;
    g.strokeRect(2, 2, w - 4, h - 4);
    g.beginPath(); g.moveTo(0, h / 2); g.lineTo(w, h / 2); g.stroke();
    g.fillStyle = 'rgba(0,0,0,0.5)';
    for (const [x, y] of [[10, 10], [w - 14, 10], [10, h - 14], [w - 14, h - 14], [10, h / 2 - 12], [w - 14, h / 2 - 12]]) {
      g.beginPath(); g.arc(x + 2, y + 2, 3, 0, 7); g.fill();
    }
    g.fillStyle = 'rgba(120,70,20,0.12)';
    for (let i = 0; i < 12; i++) g.fillRect(Math.random() * w, Math.random() * h, 20 + Math.random() * 60, 3 + Math.random() * 10);
  });
}
